contracts/AAOTestToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract AAOTestToken is ERC20, Ownable, Pausable {
    enum RewardTier { FULL, PARTIAL, NONE }

    struct TokenMintRecord {
        uint256 mintId;
        address agent;
        uint256 amount;
        bytes32 taskHash;
        bytes32 callRecordHash;
        uint256 timestamp;
        RewardTier tier;
    }

    mapping(address => bool) public authorizedMinters;
    mapping(uint256 => TokenMintRecord) public mintRecords;
    mapping(address => uint256[]) private _agentMintIds;
    mapping(bytes32 => bool) public mintedTaskHashes;

    uint256 public nextMintId;
    uint256 public rewardAmount;

    event MinterAdded(address indexed minter);
    event MinterRemoved(address indexed minter);
    event TokenMinted(
        uint256 indexed mintId,
        address indexed agent,
        uint256 amount,
        bytes32 taskHash,
        RewardTier tier
    );
    event RewardAmountUpdated(uint256 oldAmount, uint256 newAmount);

    modifier onlyAuthorizedMinter() {
        require(authorizedMinters[msg.sender], "Not authorized minter");
        _;
    }

    constructor(uint256 _rewardAmount) ERC20("AAO Test Token", "AAOT") Ownable(msg.sender) {
        rewardAmount = _rewardAmount;
    }

    function setRewardAmount(uint256 _rewardAmount) external onlyOwner {
        uint256 old = rewardAmount;
        rewardAmount = _rewardAmount;
        emit RewardAmountUpdated(old, _rewardAmount);
    }

    function addMinter(address minter) external onlyOwner {
        require(minter != address(0), "Zero address");
        authorizedMinters[minter] = true;
        emit MinterAdded(minter);
    }

    function removeMinter(address minter) external onlyOwner {
        authorizedMinters[minter] = false;
        emit MinterRemoved(minter);
    }

    function mint(
        address agent,
        uint256 amount,
        bytes32 taskHash,
        bytes32 callRecordHash,
        RewardTier tier
    ) external onlyAuthorizedMinter whenNotPaused returns (uint256 mintId) {
        require(agent != address(0), "Zero agent address");
        require(amount > 0, "Zero amount");
        require(!mintedTaskHashes[taskHash], "Task already minted");

        mintedTaskHashes[taskHash] = true;

        mintId = nextMintId++;
        mintRecords[mintId] = TokenMintRecord({
            mintId: mintId,
            agent: agent,
            amount: amount,
            taskHash: taskHash,
            callRecordHash: callRecordHash,
            timestamp: block.timestamp,
            tier: tier
        });
        _agentMintIds[agent].push(mintId);

        _mint(agent, amount);

        emit TokenMinted(mintId, agent, amount, taskHash, tier);
    }

    function isTaskMinted(bytes32 taskHash) external view returns (bool) {
        return mintedTaskHashes[taskHash];
    }

    function getMintRecord(uint256 mintId) external view returns (TokenMintRecord memory) {
        require(mintId < nextMintId, "Mint record does not exist");
        return mintRecords[mintId];
    }

    function getMintsByAgent(address agent) external view returns (uint256[] memory) {
        return _agentMintIds[agent];
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/AAOVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./AAOTestToken.sol";

contract AAOVault is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public usdc;
    AAOTestToken public testToken;
    bool public redemptionEnabled;

    mapping(address => uint256) public builderDeposits;
    mapping(bytes32 => bool) public processedRedemptions;

    struct RedemptionRequest {
        address agent;
        uint256 tokenAmount;
        uint256[] mintIds;
        uint256 usdcAmount;
    }

    event Deposited(address indexed builder, uint256 amount);
    event RedemptionToggled(bool enabled);
    event RedemptionProcessed(
        address indexed agent,
        uint256 tokenAmount,
        uint256 usdcAmount,
        bytes32 redemptionHash
    );
    event EmergencyWithdraw(address indexed owner, uint256 amount);

    constructor(address _usdc, address _testToken) Ownable(msg.sender) {
        require(_usdc != address(0), "Zero USDC address");
        require(_testToken != address(0), "Zero token address");
        usdc = IERC20(_usdc);
        testToken = AAOTestToken(_testToken);
        redemptionEnabled = false;
    }

    /// @notice Builder deposits directly (msg.sender is builder)
    function deposit(uint256 usdcAmount) external {
        require(usdcAmount > 0, "Zero amount");
        usdc.safeTransferFrom(msg.sender, address(this), usdcAmount);
        builderDeposits[msg.sender] += usdcAmount;
        emit Deposited(msg.sender, usdcAmount);
    }

    /// @notice Operator deposits on behalf of builder (backend pattern)
    function depositFor(address builder, uint256 usdcAmount) external onlyOwner {
        require(builder != address(0), "Zero builder address");
        require(usdcAmount > 0, "Zero amount");
        usdc.safeTransferFrom(msg.sender, address(this), usdcAmount);
        builderDeposits[builder] += usdcAmount;
        emit Deposited(builder, usdcAmount);
    }

    function getBuilderBalance(address builder) external view returns (uint256) {
        return builderDeposits[builder];
    }

    function toggleRedemption(bool enabled) external onlyOwner {
        redemptionEnabled = enabled;
        emit RedemptionToggled(enabled);
    }

    /// @notice Redemption (placeholder — disabled by default, future feature)
    function requestRedemption(RedemptionRequest calldata req) external nonReentrant {
        require(redemptionEnabled, "Redemption disabled");
        require(msg.sender == req.agent, "Caller must be agent");
        require(req.tokenAmount > 0, "Zero token amount");
        require(req.usdcAmount > 0, "Zero USDC amount");

        bytes32 redemptionHash = keccak256(
            abi.encodePacked(req.agent, req.tokenAmount, req.usdcAmount, block.timestamp)
        );
        require(!processedRedemptions[redemptionHash], "Already processed");

        require(_validateRedemption(req), "Validation failed");

        processedRedemptions[redemptionHash] = true;

        // Transfer test tokens from agent to vault (burn equivalent)
        IERC20(address(testToken)).safeTransferFrom(req.agent, address(this), req.tokenAmount);

        // Transfer USDC to agent
        usdc.safeTransfer(req.agent, req.usdcAmount);

        emit RedemptionProcessed(req.agent, req.tokenAmount, req.usdcAmount, redemptionHash);
    }

    function _validateRedemption(RedemptionRequest calldata req) internal view returns (bool) {
        // 1. Agent holds enough tokens
        if (testToken.balanceOf(req.agent) < req.tokenAmount) return false;

        // 2. All mintIds exist and belong to this agent
        uint256 totalMintedAmount;
        for (uint256 i = 0; i < req.mintIds.length; i++) {
            uint256 mintId = req.mintIds[i];
            if (mintId >= testToken.nextMintId()) return false;

            (
                ,
                address agent,
                uint256 amount,
                ,
                ,
                ,
            ) = testToken.mintRecords(mintId);

            if (agent != req.agent) return false;
            totalMintedAmount += amount;
        }

        // 3. Requested token amount doesn't exceed minted total from these IDs
        if (req.tokenAmount > totalMintedAmount) return false;

        // 4. Vault has enough USDC
        if (usdc.balanceOf(address(this)) < req.usdcAmount) return false;

        return true;
    }

    function withdraw(uint256 amount) external onlyOwner {
        require(usdc.balanceOf(address(this)) >= amount, "Insufficient balance");
        usdc.safeTransfer(msg.sender, amount);
        emit EmergencyWithdraw(msg.sender, amount);
    }
}

contracts/AgentRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract AgentRegistry is Ownable, Pausable {
    struct AgentProfile {
        address wallet;
        address operator;
        bytes32 agentIdHash;
        uint256 registeredAt;
        bool isActive;
        uint256 totalEarned;
        uint256 taskCount;
    }

    mapping(address => AgentProfile) public agents;
    mapping(bytes32 => address) public agentIdToWallet;

    event AgentRegistered(address indexed wallet, bytes32 indexed agentIdHash);
    event AgentDeactivated(address indexed wallet);
    event AgentStatsUpdated(address indexed wallet, uint256 totalEarned, uint256 taskCount);

    constructor() Ownable(msg.sender) {}

    /// @notice Self-register (caller is the agent wallet)
    function registerAgent(bytes32 agentIdHash) external whenNotPaused {
        require(agents[msg.sender].wallet == address(0), "Already registered");
        require(agentIdToWallet[agentIdHash] == address(0), "AgentId already taken");

        agents[msg.sender] = AgentProfile({
            wallet: msg.sender,
            operator: msg.sender,
            agentIdHash: agentIdHash,
            registeredAt: block.timestamp,
            isActive: true,
            totalEarned: 0,
            taskCount: 0
        });
        agentIdToWallet[agentIdHash] = msg.sender;

        emit AgentRegistered(msg.sender, agentIdHash);
    }

    /// @notice Register on behalf of agent (operator/backend pattern)
    function registerAgentFor(address wallet, bytes32 agentIdHash) external onlyOwner whenNotPaused {
        require(wallet != address(0), "Zero address");
        require(agents[wallet].wallet == address(0), "Already registered");
        require(agentIdToWallet[agentIdHash] == address(0), "AgentId already taken");

        agents[wallet] = AgentProfile({
            wallet: wallet,
            operator: msg.sender,
            agentIdHash: agentIdHash,
            registeredAt: block.timestamp,
            isActive: true,
            totalEarned: 0,
            taskCount: 0
        });
        agentIdToWallet[agentIdHash] = wallet;

        emit AgentRegistered(wallet, agentIdHash);
    }

    function deactivateAgent(address wallet) external onlyOwner {
        require(agents[wallet].wallet != address(0), "Agent not found");
        agents[wallet].isActive = false;
        emit AgentDeactivated(wallet);
    }

    function getAgentProfile(address wallet) external view returns (AgentProfile memory) {
        return agents[wallet];
    }

    function isRegisteredAgent(address wallet) external view returns (bool) {
        return agents[wallet].wallet != address(0) && agents[wallet].isActive;
    }

    function updateAgentStats(address wallet, uint256 earned, uint256 tasks) external onlyOwner {
        require(agents[wallet].wallet != address(0), "Agent not found");
        agents[wallet].totalEarned += earned;
        agents[wallet].taskCount += tasks;
        emit AgentStatsUpdated(wallet, agents[wallet].totalEarned, agents[wallet].taskCount);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

